import sys

def count_palindromic_substrings(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    count = 0

    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j]:
                if j - i <= 1:
                    dp[i][j] = True
                else:
                    dp[i][j] = dp[i + 1][j - 1]
            if dp[i][j]:
                count += 1

    return count

input = sys.stdin.read().strip()
n = int(input.split()[0])
s = input.split()[1]
print(count_palindromic_substrings(s))
